com.mirth.connect.plugins.javascriptstep.script:
var rawMessage = (typeof connectorMessage !== 'undefined' && connectorMessage && typeof connectorMessage.getRawData === 'function')
    ? String(connectorMessage.getRawData())
    : String(msg || '');

var segments = rawMessage.split(/\r\n|\r|\n/);
var mshSegment = '';
for (var i = 0; i < segments.length; i++) {
    if (segments[i].indexOf('MSH') === 0) {
        mshSegment = segments[i];
        break;
    }
}

var fieldSep = mshSegment.length > 3 ? mshSegment.charAt(3) : '|';
var compSep = mshSegment.length > 4 ? mshSegment.charAt(4) : '^';
var repSep = mshSegment.length > 5 ? mshSegment.charAt(5) : '~';
var fields = mshSegment ? mshSegment.split(fieldSep) : [];

var msh10 = fields.length > 9 ? String(fields[9] || '').trim() : '';
channelMap.put('msh10', msh10);
channelMap.put('msh3', fields.length > 2 ? String(fields[2] || '') : '');
channelMap.put('msh4', fields.length > 3 ? String(fields[3] || '') : '');
channelMap.put('msh5', fields.length > 4 ? String(fields[4] || '') : '');
channelMap.put('msh6', fields.length > 5 ? String(fields[5] || '') : '');
channelMap.put('msh11', fields.length > 10 && fields[10] ? String(fields[10]) : 'P');
channelMap.put('msh12', fields.length > 11 && fields[11] ? String(fields[11]) : '2.5');

var msh9Field = fields.length > 8 ? String(fields[8] || '').split(repSep)[0] : '';
var msh9Comps = msh9Field ? msh9Field.split(compSep) : [];
var msh9Type = (msh9Comps[0] || '').trim();
var msh9Trigger = (msh9Comps[1] || '').trim();
var msh9Structure = (msh9Comps[2] || '').trim();

var templateName = 'ADT_A01';
if (/^[A-Za-z0-9]+_[A-Za-z0-9]+$/.test(msh9Structure)) {
    templateName = msh9Structure;
} else if (/^[A-Za-z0-9]+$/.test(msh9Type) && /^[A-Za-z0-9]+$/.test(msh9Trigger)) {
    templateName = msh9Type + '_' + msh9Trigger;
}
channelMap.put('templateName', templateName);

var converterPayload = JSON.stringify({
    srcData: rawMessage,
    template: templateName
});
channelMap.put('converterPayload', converterPayload);

var apiKey = (typeof configurationMap !== 'undefined' && configurationMap && typeof configurationMap.get === 'function')
    ? String(configurationMap.get('CONVERT_API_KEY') || '').trim()
    : '';
channelMap.put('authHeader', apiKey ? ('Bearer ' + apiKey) : '');

var statusCode = 0;
if (typeof httpStatus === 'number') {
    statusCode = httpStatus;
} else if (typeof connectorMap !== 'undefined' && connectorMap && typeof connectorMap.get === 'function' && connectorMap.get('responseStatusLine')) {
    var statusMatch = String(connectorMap.get('responseStatusLine')).match(/HTTP\/\d+(?:\.\d+)?\s+(\d{3})/);
    if (statusMatch) {
        statusCode = parseInt(statusMatch[1], 10);
    }
} else if (typeof response !== 'undefined' && response && typeof response.getStatusMessage === 'function') {
    var msgMatch = String(response.getStatusMessage() || '').match(/\b(\d{3})\b/);
    if (msgMatch) {
        statusCode = parseInt(msgMatch[1], 10);
    }
}

var msh10 = String(channelMap.get('msh10') || '');
var sendApp = String(channelMap.get('msh3') || '');
var sendFac = String(channelMap.get('msh4') || '');
var recvApp = String(channelMap.get('msh5') || 'OIE');
var recvFac = String(channelMap.get('msh6') || '');
var procId = String(channelMap.get('msh11') || 'P');
var versionId = String(channelMap.get('msh12') || '2.5');

var now = new Date();
var pad2 = function (n) {
    return (n < 10 ? '0' : '') + n;
};
var ts = String(now.getUTCFullYear())
    + pad2(now.getUTCMonth() + 1)
    + pad2(now.getUTCDate())
    + pad2(now.getUTCHours())
    + pad2(now.getUTCMinutes())
    + pad2(now.getUTCSeconds());

var isSuccess = statusCode >= 200 && statusCode < 300;
var mshOut = 'MSH|^~\\&|' + recvApp + '|' + recvFac + '|' + sendApp + '|' + sendFac + '|' + ts + '||ACK|ACK' + msh10 + '|' + procId + '|' + versionId;
var msaOut = isSuccess
    ? ('MSA|AA|' + msh10)
    : ('MSA|AE|' + msh10 + '|Conversion failed');
var ackMessage = mshOut + '\r' + msaOut + '\r';

channelMap.put('hl7Ack', ackMessage);
if (typeof responseMap !== 'undefined' && responseMap && typeof responseMap.put === 'function') {
    responseMap.put('ackResponse', ackMessage);
}
return ackMessage;
